begin;
select plan(8);
select has_function('public', 'finish_quest_early', array['uuid','uuid','uuid']);
select ok(not has_function_privilege('anon', 'public.finish_quest_early(uuid,uuid,uuid)', 'execute'), 'anonymous cannot finish attempts');
insert into auth.users(id,email) values ('ad000000-0000-4000-8000-000000000001','finish-owner@example.test');
insert into public.quests(id,creator_id,title,is_public) values ('ad100000-0000-4000-8000-000000000001','ad000000-0000-4000-8000-000000000001','Early finish',true);
insert into public.tasks(id,quest_id,title) values ('ad200000-0000-4000-8000-000000000001','ad100000-0000-4000-8000-000000000001','Unanswered');
select set_config('request.jwt.claim.sub','ad000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.finish_quest_early('ad100000-0000-4000-8000-000000000001','ad200000-0000-4000-8000-000000000001','ad300000-0000-4000-8000-000000000001')$$,'42501','quest attempt access denied','inaccessible attempt cannot be finished');
select throws_ok($$select public.finish_quest_early('ad100000-0000-4000-8000-000000000001','ad200000-0000-4000-8000-000000000001',null)$$,'22023','client_event_id required','event identity is required');
select set_config('app.finish_attempt',(select id::text from public.start_quest_attempt('ad100000-0000-4000-8000-000000000001')),true);
select set_config('app.finish_result',public.finish_quest_early(current_setting('app.finish_attempt')::uuid,'ad200000-0000-4000-8000-000000000001','ad300000-0000-4000-8000-000000000001')::text,true);
select ok(current_setting('app.finish_result')::jsonb #>> '{quest_attempt,finished_at}' is not null,'attempt closes without answering task');
select is(public.finish_quest_early(current_setting('app.finish_attempt')::uuid,'ad200000-0000-4000-8000-000000000001','ad300000-0000-4000-8000-000000000001'),current_setting('app.finish_result')::jsonb,'retry returns same receipt');
select is((select count(*) from public.task_attempts where quest_attempt_id=current_setting('app.finish_attempt')::uuid),0::bigint,'no fabricated task results');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.finish_quest_early('ad100000-0000-4000-8000-000000000001','ad200000-0000-4000-8000-000000000001','ad300000-0000-4000-8000-000000000001')$$,'42501','authentication required','missing actor rejected');
select * from finish();
rollback;
